using DotImage;
using DotImage.Color;
using TiffImage = global::DotImage.Extended.Tiff.Tiff;
using Xunit;

namespace DotImage.Extended.Tests;

public class TiffLzwDecodeTests
{
    // A Pillow-generated 40x30 RGB TIFF with LZW compression (compression=5,
    // no predictor). Used as an end-to-end regression test for the LZW decoder,
    // including its off-by-one handling and clean-EOF behavior.
    private const string PillowRgbLzwBase64 =
        "";

    private static byte[] PillowRgbLzwBytes()
    {
        Span<byte> buf = new byte[PillowRgbLzwBase64.Length];
        Assert.True(Convert.TryFromBase64String(PillowRgbLzwBase64, buf, out int written));
        return buf[..written].ToArray();
    }

    private static (byte r, byte g, byte b) ExpectedPixel(int x, int y)
    {
        return ((byte)(x * 255 / 40), (byte)(y * 255 / 30), (byte)(x + y));
    }

    [Fact]
    public void DecodesPillowLzwRgb()
    {
        byte[] data = PillowRgbLzwBytes();
        using var ms = new MemoryStream(data);
        IImage dst = TiffImage.Decode(ms);

        Assert.Equal(40, dst.Bounds().Dx());
        Assert.Equal(30, dst.Bounds().Dy());
        for (int y = 0; y < 30; y++)
        {
            for (int x = 0; x < 40; x++)
            {
                (uint r, uint g, uint b, uint a) = dst.At(x, y).Rgba();
                (byte er, byte eg, byte eb) = ExpectedPixel(x, y);
                Assert.Equal((uint)er, r >> 8);
                Assert.Equal((uint)eg, g >> 8);
                Assert.Equal((uint)eb, b >> 8);
                Assert.Equal(255u, a >> 8);
            }
        }
    }
}
